sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*
    This is created as part of MSSCUSTODY-4413 which will copy over the comments provided by the maker to checker
    1) Posts the comments provided during submission of the Maker task 
    2) Posts the comments post completion of the maker task if the checker task is active.
    */

    var currTskType = current.trade_task_type.toString();
    var currTrd = current.trade_id;
    var bulkID = current.bulk_id;
    var tskQuery;
    var singleTrd = 'trade_id.sys_id=' + currTrd + '^trade_task_type=Checker^active=true';
    var bulkTrd = 'bulk_id.sys_id=' + bulkID + '^trade_task_type=Checker^active=true';

    /*
    Any comments posted in one maker task will be copied over to all active checker tasks
	Handling for Single trade and Bulk tasks are handled in the above query since trade mappings
	are different in case of bulk
    */
    if (bulkID == '') {
        tskQuery = singleTrd;
    } else {
        tskQuery = bulkTrd;
    }


    //Maker Task
    var mkrTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    mkrTask.addEncodedQuery('trade_id.sys_id=' + currTrd + '^trade_task_type=Maker');
    mkrTask.orderByDesc('sys_updated_on');
    mkrTask.setLimit(1);
    mkrTask.query();
    if (mkrTask.next()) {
        //Checker Task
        var chkTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        chkTask.addEncodedQuery(tskQuery);
        chkTask.orderByDesc('sys_created_on');
        chkTask.query();
        while (chkTask.next()) {
            chkTask.work_notes = mkrTask.comments_and_work_notes.getJournalEntry(-1); //added as part of MSSCUSTODY-4413
            chkTask.update();

        }

    }


})(current, previous);
